import re

specs = ["pandas>=2.2,<3", "requests", "sqlalchemy==2.0.30", "numpy~=2.0", "tqdm", "pytest==8.2.0"]
classes = {"pinned": [], "range": [], "unpinned": []}
for spec in specs:
    name = re.split(r"[=<>~!]", spec)[0]
    if "==" in spec:
        classes["pinned"].append(name)
    elif re.search(r"[<>~]", spec):
        classes["range"].append(name)
    else:
        classes["unpinned"].append(name)
for key in ["pinned", "range", "unpinned"]:
    print(f"{key}: " + (", ".join(sorted(classes[key])) or "none"))
